arguments.command:
python3 -c "
import pdfplumber
with pdfplumber.open('invoices.pdf') as pdf:
    for i, page in enumerate(pdf.pages):
        text = page.extract_text()
        if 'PO Number:' not in text:
            print(f'Page {i+1} missing PO Number line')
        elif 'PO Number: None' in text:
            print(f'Page {i+1} has PO Number: None')
"
